const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let line = '';
rl.on('line', (input) => {
    const s = input.trim();
    const n = s.length;
    const seen = new Set();

    for (let i = 0; i < n; i++) {
        // Generate the string after i cyclic shifts
        // After i shifts, the string is s[n-i:] + s[:n-i]
        const shifted = s.slice(n - i) + s.slice(0, n - i);
        seen.add(shifted);
    }

    console.log(seen.size);
});
