const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const s = line.trim();
    const n = s.length;
    const seen = new Set();

    for (let i = 0; i < n; i++) {
        // Generate the cyclic shift: move last i characters to front
        // Shift by 1: last char to front
        // After k shifts, the string is s[n-k..n-1] + s[0..n-k-1]
        // Or equivalently, rotate left by k: s[k..n-1] + s[0..k-1]
        // Let's think: initial is s.
        // After 1 shift: last char to front => s[n-1] + s[0..n-2]
        // After 2 shifts: s[n-2] + s[n-1] + s[0..n-3]
        // After k shifts: s[n-k..n-1] + s[0..n-k-1]

        const rotated = s.slice(n - i) + s.slice(0, n - i);
        seen.add(rotated);
    }

    console.log(seen.size);
});
```

